create or replace function public.ai_commit_turn(p_session_id uuid,p_expected jsonb,p_next jsonb,p_message text,p_answer text) returns boolean language plpgsql security invoker set search_path = '' as $$ begin update public.ai_sessions set context=p_next where id=p_session_id and context=p_expected and expires_at>now(); if not found then return false; end if; insert into public.ai_messages(session_id,role,content) values(p_session_id,'user',p_message),(p_session_id,'assistant',p_answer); return true; end; $$; revoke all on function public.ai_commit_turn(uuid,jsonb,jsonb,text,text) from public,anon,authenticated; grant execute on function public.ai_commit_turn(uuid,jsonb,jsonb,text,text) to service_role;